package com.railway.notificationservice.exception;
import org.junit.jupiter.api.Test; import org.springframework.mock.web.*; import org.springframework.web.server.ResponseStatusException; import org.springframework.http.HttpStatus; import static org.junit.jupiter.api.Assertions.*;
class ApiErrorsTest {
 @Test void unexpectedDetailsAreHiddenAndEnvelopeIsComplete(){var req=new MockHttpServletRequest();var result=new GlobalExceptionHandler().handle(new RuntimeException("private-database-password"),req);assertEquals(500,result.getStatusCode().value());var body=result.getBody();assertNotNull(body);assertEquals(java.util.Set.of("code","status","message","fieldErrors","timestamp","requestId"),body.keySet());assertFalse(body.toString().contains("private-database-password"));assertEquals(body.get("requestId"),result.getHeaders().getFirst("X-Request-ID"));}
 @Test void statusAndSecurityResponsesUseSameContract()throws Exception{var req=new MockHttpServletRequest();var result=new GlobalExceptionHandler().handle(new ResponseStatusException(HttpStatus.NOT_FOUND,"Not found"),req);assertEquals(404,result.getStatusCode().value());var res=new MockHttpServletResponse();ApiErrors.write(req,res,401,"Sign in required");assertEquals("application/json",res.getContentType().split(";")[0]);assertTrue(res.getContentAsString().contains("UNAUTHORIZED"));assertTrue(res.getContentAsString().contains("fieldErrors"));}
}
